<?php
require_role(['admin']);$base='index.php?page=users';$roles=['admin','organisateur','club','officiel','nageur','entraineur'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);
 if($action==='delete'){
  if($id===(int)$u['id']){flash('Vous ne pouvez pas supprimer votre propre compte.','error');redirect($base);}
  $q=db()->prepare('SELECT role FROM users WHERE id=?');$q->execute([$id]);$target=$q->fetchColumn();
  if($target==='admin'&&(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn()<=1){flash('Impossible de supprimer le dernier administrateur.','error');redirect($base);}
  db()->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('Utilisateur supprimé.');redirect($base);
 }
 $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$roleNew=$_POST['role']??'';$club=($_POST['club_id']??'')!==''?(int)$_POST['club_id']:null;$swimmer=($_POST['swimmer_id']??'')!==''?(int)$_POST['swimmer_id']:null;
 if($id){ // modification
  $q=db()->prepare('SELECT role FROM users WHERE id=?');$q->execute([$id]);$oldRole=$q->fetchColumn();
  if($oldRole===false){flash('Utilisateur introuvable.','error');}
  elseif(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($roleNew,$roles,true)||($password!==''&&strlen($password)<10)){flash('Vérifiez les champs (e-mail valide, rôle valide, mot de passe de 10 caractères minimum s’il est modifié).','error');}
  elseif($oldRole==='admin'&&$roleNew!=='admin'&&(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn()<=1){flash('Impossible de retirer le rôle du dernier administrateur.','error');}
  else{try{
   if($password!=='')db()->prepare('UPDATE users SET name=?,email=?,role=?,club_id=?,swimmer_id=?,password=? WHERE id=?')->execute([$name,$email,$roleNew,$club,$swimmer,password_hash($password,PASSWORD_DEFAULT),$id]);
   else db()->prepare('UPDATE users SET name=?,email=?,role=?,club_id=?,swimmer_id=? WHERE id=?')->execute([$name,$email,$roleNew,$club,$swimmer,$id]);
   if($id===(int)$u['id']){$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;$_SESSION['user']['role']=$roleNew;$_SESSION['user']['club_id']=$club;$_SESSION['user']['swimmer_id']=$swimmer;}
   flash('Utilisateur modifié.');
  }catch(Throwable $e){flash('Modification impossible : e-mail déjà utilisé ou association invalide.','error');}}
  redirect($base);
 }
 if(!in_array($roleNew,$roles,true)||strlen($password)<10){flash('Rôle invalide ou mot de passe trop court (10 caractères minimum).','error');}else{$s=db()->prepare('INSERT INTO users(name,email,password,role,club_id,swimmer_id) VALUES(?,?,?,?,?,?)');try{$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$roleNew,$club,$swimmer]);flash('Utilisateur créé.');}catch(Throwable $e){flash('Création impossible : e-mail déjà utilisé ou association invalide.','error');}}redirect($base);}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
?>
<div class="grid2"><section class="panel"><h3><?=$edit?'Modifier l’utilisateur':'Créer un utilisateur'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Nom</label><input name="name" required value="<?=e($edit['name']??'')?>"><label>E-mail</label><input type="email" name="email" required value="<?=e($edit['email']??'')?>"><label><?=$edit?'Nouveau mot de passe (laisser vide pour ne pas le changer)':'Mot de passe initial'?></label><input type="password" name="password" minlength="10" <?=$edit?'':'required'?> autocomplete="new-password"><label>Rôle</label><select name="role"><?php foreach($roles as $r):?><option <?=($edit['role']??'admin')===$r?'selected':''?>><?=e($r)?></option><?php endforeach;?></select><label>Club associé (si nécessaire)</label><select name="club_id"><option value="">Aucun</option><?php foreach(db()->query('SELECT id,name FROM clubs') as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['club_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label>Profil nageur (pour rôle nageur)</label><select name="swimmer_id"><option value="">Aucun</option><?php foreach(db()->query('SELECT id,first_name,last_name FROM swimmers') as $s):?><option value="<?=$s['id']?>" <?=((int)($edit['swimmer_id']??0)===(int)$s['id'])?'selected':''?>><?=e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select><button class="btn primary"><?=$edit?'Enregistrer les modifications':'Créer le compte'?></button><?php if($edit):?> <a class="btn light" href="<?=$base?>">Annuler</a><?php endif;?></form></section><section class="panel"><h3>Comptes existants</h3><div class="table-wrap"><table><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Club</th><th>Actions</th></tr><?php foreach(db()->query('SELECT u.*,c.name club FROM users u LEFT JOIN clubs c ON c.id=u.club_id ORDER BY u.id') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['club']??'—')?></td><td class="actions"><a class="link" href="<?=$base?>&edit=<?=$r['id']?>">Modifier</a><?php if((int)$r['id']!==(int)$u['id']):?><form class="inline" method="post" onsubmit="return confirm('Supprimer ce compte utilisateur ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Supprimer</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section></div>
